 async function saveDesign(){setSaving(true);setSaveMessage("");const db=getSupabase();if(!db){setSaveMessage("Connect a student account to save designs across devices.");setSaving(false);return;}const {data:{user}}=await db.auth.getUser();if(!user){window.location.href="/account";setSaving(false);return;}const snapshot={length,width,budget,rate,floors,wallHeight,roof,material,name,checks,explanation};const {error}=await db.from("saved_designs").upsert({user_id:user.id,challenge_key:challengeKey,project_name:name,design_snapshot:snapshot,updated_at:new Date().toISOString()},{onConflict:"user_id,challenge_key"});setSaveMessage(error?`Save failed: ${error.message}`:"Design saved to your student account.");setSaving(false);}
 async function completeChallenge(){const db=getSupabase();if(!db){setCompletionMessage("Connect your student account to record a completion and issue a certificate.");return;}const {data:{user}}=await db.auth.getUser();if(!user){window.location.href="/account";return;}const {data,error}=await db.from("challenge_completions").upsert({user_id:user.id,challenge_key:challengeKey,project_name:name,score,completed_at:new Date().toISOString()},{onConflict:"user_id,challenge_key"}).select("id").single();if(error){setCompletionMessage(`Could not record completion: ${error.message}`);return;}setCompletionId(data.id);setCompletionMessage("Challenge completed! Your certificate is ready.");}
 const current=floors[floorIndex]||floors[0];
